<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_role('admin');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim($_POST['title']??'');$category=trim($_POST['category']??'General');$eventDate=$_POST['event_date']??date('Y-m-d');$description=trim($_POST['description']??'');$poster=null;if(!empty($_FILES['poster']['name'])){$f=$_FILES['poster'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!isset($allowed[$mime]))$msg='Poster must be JPG, PNG or WEBP and at most 2 MB.';else{$poster=bin2hex(random_bytes(12)).'.'.$allowed[$mime];move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/posters/'.$poster);}}if(!$msg&&$title!==''){$s=$conn->prepare('INSERT INTO events(title,category,event_date,description,poster,created_by) VALUES(?,?,?,?,?,?)');$uid=(int)$_SESSION['user_id'];$s->bind_param('sssssi',$title,$category,$eventDate,$description,$poster,$uid);$msg=$s->execute()?'Event created.':'Could not create event.';$s->close();audit($conn,'event.create',$title);}elseif(!$msg)$msg='Event title is required.';}$rows=$conn->query('SELECT id,title,category,event_date FROM events ORDER BY event_date DESC');require __DIR__.'/../includes/header.php'; ?><h1>Event management</h1><?php if($msg): ?><p class="notice"><?= e($msg) ?></p><?php endif; ?><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><h2>Create event</h2><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Category</label><input name="category" value="Workshop"></div><div class="field"><label>Date</label><input type="date" name="event_date" required></div><div class="field"><label>Description</label><textarea name="description" required></textarea></div><div class="field"><label>Poster (JPG, PNG, WEBP; max 2 MB)</label><input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></div><button class="button">Save event</button></form><h2>Saved events</h2><div class="table-wrap"><table><tr><th>ID</th><th>Title</th><th>Category</th><th>Date</th></tr><?php foreach($rows as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= e($r['title']) ?></td><td><?= e($r['category']) ?></td><td><?= e($r['event_date']) ?></td></tr><?php endforeach; ?></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
